import type { T } from './lang';

// Every rule of The Racing Rules of Sailing 2025–2028 (with World Sailing's changes and corrections to 20 April 2026),
// for /learn/rulebook: each in a sentence or a few of our own words, in the book's order. A summary to find your way
// by, not the official text, which is World Sailing's (RULEBOOK_SOURCE); the page says so.
export const RULEBOOK_DATE = '2026-11-18';
export const RULEBOOK_SOURCE = 'https://www.sailing.org/racingrules';

export type PartId = 'definitions' | 'principles' | 'part-1' | 'part-2' | 'part-3' | 'part-4' | 'part-5' | 'part-6' | 'part-7' | 'appendices' | 'signals';
export type RuleEntry = { id: string; no?: string; title: string; text: string; see?: string };
export type RuleSection = { id?: string; title?: string; intro?: string; entries: RuleEntry[] };
export type RulePart = { id: PartId; chip: string; title: string; intro: string; sections: RuleSection[] };

type Pair = [en: string, ru: string];

export const entriesOf = (p: RulePart) => p.sections.flatMap((s) => s.entries);
// the numbered rules of Parts 1 to 7, a rule told in parts (18.1 to 18.4) counted once
export const ruleCount = (parts: RulePart[]) => new Set(parts.filter((p) => p.id.startsWith('part-')).flatMap(entriesOf).map((e) => e.no!.split('.')[0])).size;

export function rulebook(t: T): RulePart[] {
  const def = (id: string, title: Pair, text: Pair): RuleEntry => ({ id: `def-${id}`, title: t(...title), text: t(...text) });
  const rule = (no: string, title: Pair, text: Pair, see?: string): RuleEntry => ({ id: `rule-${no.replace('.', '-')}`, no, title: t(...title), text: t(...text), see });
  const app = (no: string, title: Pair, text: Pair): RuleEntry => ({ id: `appendix-${no.toLowerCase()}`, no, title: t(...title), text: t(...text) });
  const sig = (id: string, no: string, title: Pair, text: Pair): RuleEntry => ({ id: `signal-${id}`, no: no || undefined, title: t(...title), text: t(...text) });
  const sec = (id: string, title: Pair, intro: Pair | null, entries: RuleEntry[]): RuleSection => ({ id, title: t(...title), intro: intro ? t(...intro) : undefined, entries });

  return [
    { id: 'definitions', chip: t('Definitions', 'Определения'), title: t('Definitions', 'Определения'),
      intro: t('The words the rules use in an exact sense. Most arguments on the water come down to one of these.', 'Слова, которые правила понимают в точном смысле. Большинство споров на воде сводится к одному из них.'),
      sections: [{ entries: [
        def('abandon', ['Abandon', 'Прекращение гонки'], ['A race abandoned by the race committee or the protest committee doesn’t count. It may be sailed again.', 'Гонка, прекращённая гоночным или протестовым комитетом, не считается. Её можно провести заново.']),
        def('overlap', ['Clear astern, clear ahead, overlap', 'Чисто позади, чисто впереди, связанность'], ['A boat is clear astern when her hull and equipment in normal position are behind a line square across the aftermost point of the other boat, which is clear ahead. If neither is clear astern they overlap, and a boat between two others can link them. On opposite tacks these words apply only when rule 18 applies between the boats or both are sailing more than 90° from the true wind.', 'Лодка чисто позади, когда её корпус и снаряжение в обычном положении находятся за линией, проведённой поперёк через самую кормовую точку другой лодки; та — чисто впереди. Если ни одна не чисто позади, они связаны, а лодка между двумя другими может связать их. На разных галсах эти слова действуют, только если между лодками применяется правило 18 или обе идут дальше 90° от истинного ветра.']),
        def('committee', ['Committee', 'Комитет'], ['The protest committee, the race committee or the technical committee.', 'Протестовый, гоночный или технический комитет.']),
        def('conflict', ['Conflict of interest', 'Конфликт интересов'], ['A person has one if they could gain or lose by a decision they help to make, could reasonably seem to have a personal or financial stake that affects their impartiality, or have a close personal interest in the decision.', 'Он есть у человека, который может выиграть или проиграть от решения, в котором участвует, может обоснованно казаться лично или финансово заинтересованным либо имеет к решению близкий личный интерес.']),
        def('continuing', ['Continuing obstruction', 'Протяжённое препятствие'], ['An obstruction the boat with the shortest hull involved will sail alongside for at least three of her hull lengths. A vessel under way, a boat racing and a committee boat that is also a mark are never one.', 'Препятствие, вдоль которого лодка с самым коротким корпусом из участвующих пройдёт не меньше трёх своих корпусов. Судно на ходу, лодка в гонке и судно комитета, служащее знаком, такими не бывают.']),
        def('fetching', ['Fetching', 'Лежать на знак'], ['A boat is fetching a mark when she can pass to windward of it and leave it on the required side without changing tack.', 'Лодка лежит на знак, когда может пройти его с наветра и оставить с нужной стороны, не меняя галса.']),
        def('finish', ['Finish', 'Финиш'], ['A boat finishes when, after her starting signal, any part of her hull crosses the finishing line from the course side. She hasn’t finished if she then takes a penalty turn, corrects a mistake made at the line or sails on with the course. She need not cross the line completely.', 'Лодка финиширует, когда после своего стартового сигнала любая часть её корпуса пересекает финишную линию со стороны дистанции. Она не финишировала, если затем выполняет штрафной оборот, исправляет ошибку, сделанную на линии, или продолжает проходить дистанцию. Пересекать линию полностью не обязательно.']),
        def('keep-clear', ['Keep clear', 'Уступать'], ['A boat keeps clear when the right-of-way boat can sail her course with no need to take avoiding action and, if they are overlapped, can also change course either way without touching her at once.', 'Лодка уступает, когда лодка с правом дороги может идти своим курсом, ничего не предпринимая, чтобы её избежать, а если они связаны — ещё и менять курс в обе стороны без немедленного касания.']),
        def('leeward', ['Leeward and windward', 'Подветренная и наветренная'], ['The leeward side is the side away from the wind; sailing by the lee or dead downwind, it is the side the mainsail lies on. Of two overlapped boats on the same tack, the one on the other’s leeward side is the leeward boat and the other the windward boat.', 'Подветренный борт — тот, что дальше от ветра; при ходе с ветром с подветренного борта или прямо по ветру — тот, на котором лежит грот. Из двух связанных лодок на одном галсе та, что с подветренного борта другой, — подветренная, другая — наветренная.']),
        def('mark', ['Mark', 'Знак'], ['An object the sailing instructions say to leave on a given side, a race committee vessel in navigable water at the end of the starting or finishing line, and anything deliberately attached to them. The anchor line is not part of the mark.', 'Предмет, который гоночная инструкция велит оставить с определённой стороны, судно гоночного комитета на судоходной воде, от которого идёт стартовая или финишная линия, и всё, что к ним намеренно прикреплено. Якорный конец частью знака не считается.']),
        def('mark-room', ['Mark-room', 'Место у знака'], ['Room for a boat to sail to the mark when her proper course takes her close to it, to round or pass it on the required side, and to leave it astern.', 'Место, чтобы подойти к знаку, когда надлежащий курс ведёт близко к нему, обогнуть или пройти его с нужной стороны и оставить за кормой.']),
        def('obstruction', ['Obstruction', 'Препятствие'], ['An object a boat could not pass without changing course substantially if she were one hull length away and heading straight at it, an object that is safe to pass on one side only, or an object, area or line a rule names as one. A boat racing is an obstruction only to boats that must keep clear of her or, under rule 22, avoid her.', 'Предмет, который лодка не смогла бы пройти без существенного изменения курса, идя прямо на него в одном корпусе от него; предмет, который безопасно обойти только с одной стороны; либо предмет, район или линия, названные препятствием в правиле. Лодка в гонке — препятствие только для тех, кто должен ей уступать или, по правилу 22, избегать её.']),
        def('party', ['Party', 'Сторона'], ['Those a hearing is about: the protestor and the protestee, a boat seeking redress, the committee or body whose action is questioned, a person accused of misconduct, and a support person being heard. The protest committee is never a party.', 'Те, кого касается рассмотрение: протестующий и опротестованный, лодка, просящая исправить результат, комитет или орган, чьи действия под вопросом, человек, обвинённый в проступке, и сопровождающее лицо, чьё дело рассматривается. Протестовый комитет стороной не бывает.']),
        def('postpone', ['Postpone', 'Откладывание'], ['A postponed race is delayed before its scheduled start. It may start later or be abandoned.', 'Отложенная гонка задерживается до назначенного старта. Её могут начать позже или прекратить.']),
        def('proper-course', ['Proper course', 'Надлежащий курс'], ['The course a boat would choose to sail the course as quickly as possible if the other boats named in the rule weren’t there. Before her starting signal a boat has no proper course.', 'Курс, который лодка выбрала бы, чтобы пройти дистанцию как можно быстрее, если бы названных в правиле лодок не было. До своего стартового сигнала надлежащего курса у лодки нет.']),
        def('protest', ['Protest', 'Протест'], ['An allegation under rule 60, by a boat or a committee, that a boat has broken a rule.', 'Заявление лодки или комитета по правилу 60 о том, что лодка нарушила правило.']),
        def('racing', ['Racing', 'В гонке'], ['A boat is racing from her preparatory signal until she has finished and cleared the finishing line and marks, or retired, or until the race committee signals a general recall, a postponement or an abandonment.', 'Лодка в гонке с подготовительного сигнала и до тех пор, пока не финишировала и не отошла от финишной линии и знаков, не вышла из гонки либо пока гоночный комитет не дал сигнал общего отзыва, откладывания или прекращения.']),
        def('room', ['Room', 'Место'], ['The space a boat needs in the conditions at the time, manoeuvring promptly and in a seamanlike way, including the space to meet her duties under Part 2 and rule 31.', 'Пространство, нужное лодке в данных условиях при быстром и грамотном маневрировании, включая место, чтобы выполнить обязанности по части 2 и правилу 31.']),
        def('rule', ['Rule', 'Правило'], ['What binds a race: this book (but not the Basic Principles or the titles), World Sailing regulations with the status of a rule, national prescriptions, class rules, the notice of race, the sailing instructions and any other document governing the event.', 'То, что обязательно в гонке: эта книга (кроме основных принципов и заголовков), регламенты World Sailing со статусом правила, предписания национальной федерации, правила класса, положение о соревновании, гоночная инструкция и другие документы, регулирующие соревнование.']),
        def('sail-the-course', ['Sail the course', 'Пройти дистанцию'], ['A boat starts; a string following her track, pulled taut, passes each mark on the required side and in the right order, touches each rounding mark the sailing instructions name and goes through each gate from the direction of the previous mark; then she finishes.', 'Лодка стартует; нить, повторяющая её путь, если её натянуть, проходит каждый знак с нужной стороны и в нужном порядке, касается каждого знака огибания, названного в инструкции, и проходит ворота со стороны предыдущего знака; затем лодка финиширует.']),
        def('start', ['Start', 'Старт'], ['A boat starts when, with her hull wholly on the pre-start side at or after her starting signal and rule 30.1 met if it applies, any part of her hull crosses the starting line to the course side.', 'Лодка стартует, когда в момент своего стартового сигнала или позже её корпус целиком на предстартовой стороне, правило 30.1, если оно действует, выполнено, и любая часть корпуса пересекает стартовую линию в сторону дистанции.']),
        def('support-person', ['Support person', 'Сопровождающее лицо'], ['Anyone who gives or may give a competitor physical or advisory support, such as a coach, trainer, manager or medic, and any competitor’s parent or guardian.', 'Любой, кто оказывает или может оказать гонщику физическую помощь или советы — тренер, менеджер, медик и другие, — а также родитель или опекун гонщика.']),
        def('tack', ['Tack, starboard or port', 'Галс, правый или левый'], ['A boat is on the tack of her windward side: wind on her starboard side, starboard tack.', 'Галс лодки определяется её наветренным бортом: ветер в правый борт — правый галс.']),
        def('zone', ['Zone', 'Зона'], ['The area around a mark within three hull lengths of the boat nearer to it. A boat is in the zone as soon as any part of her hull is.', 'Область вокруг знака в пределах трёх корпусов лодки, которая ближе к нему. Лодка в зоне, как только в неё вошла любая часть корпуса.']),
      ] }] },

    { id: 'principles', chip: t('Principles', 'Принципы'), title: t('Basic principles', 'Основные принципы'),
      intro: t('The two ideas the sport rests on. No event may change them.', 'Две идеи, на которых держится спорт. Ни одно соревнование не может их изменить.'),
      sections: [{ entries: [
        def('sportsmanship', ['Sportsmanship and the rules', 'Спортивное поведение и правила'], ['Sailors are expected to follow the rules and enforce them. A boat that breaks a rule and isn’t exonerated promptly takes a penalty or other fitting action, which may be to retire.', 'Гонщики сами соблюдают правила и следят за их соблюдением. Лодка, нарушившая правило и не освобождённая от ответственности, сразу выполняет наказание или другое подходящее действие — вплоть до выхода из гонки.']),
        def('environment', ['Environmental responsibility', 'Забота об окружающей среде'], ['Everyone taking part is encouraged to keep the sport’s harm to the environment as small as they can.', 'Всем участникам предлагается как можно меньше вредить окружающей среде.']),
      ] }] },

    { id: 'part-1', chip: t('Part 1', 'Часть 1'), title: t('Part 1 · Fundamental rules', 'Часть 1 · Основополагающие правила'),
      intro: t('Safety, fair play and what you agree to by taking part.', 'Безопасность, честная борьба и то, на что вы соглашаетесь, выходя на старт.'),
      sections: [{ entries: [
        rule('1', ['Safety', 'Безопасность'], ['Give all possible help to any person or vessel in danger (1.1). Carry adequate life-saving equipment for everyone aboard, one item ready for immediate use, and each competitor is responsible for wearing a personal flotation device fit for the conditions (1.2).', 'Оказывайте всю возможную помощь любому человеку или судну в опасности (1.1). Имейте на борту достаточные спасательные средства на всех, одно из них — наготове; каждый гонщик сам отвечает за то, чтобы носить спасательный жилет, подходящий к условиям (1.2).']),
        rule('2', ['Fair sailing', 'Честная гонка'], ['A boat and her owner compete by the recognised principles of sportsmanship and fair play. A boat is penalised under this rule only when a breach is clearly established, and the penalty is a disqualification she can’t discard.', 'Лодка и её владелец соревнуются по признанным принципам спортивного поведения и честной игры. Наказание по этому правилу возможно, только если нарушение ясно установлено, и это дисквалификация, которую нельзя исключить из зачёта.']),
        rule('3', ['Decision to race', 'Решение участвовать в гонке'], ['Whether to race, or to carry on racing, is the boat’s decision alone.', 'Участвовать ли в гонке и продолжать ли её — решение только самой лодки.']),
        rule('4', ['Acceptance of the rules', 'Принятие правил'], ['By taking part, competitors, owners and support persons accept the rules and the penalties given under them, subject to appeal, and agree not to take such a matter to a court or tribunal the rules don’t provide for. The person in charge makes sure the crew and the owner know this.', 'Участвуя, гонщики, владельцы и сопровождающие лица принимают правила и наказания по ним, с учётом права на апелляцию, и соглашаются не обращаться по этим вопросам в суды, не предусмотренные правилами. Ответственный на лодке следит, чтобы экипаж и владелец об этом знали.']),
        rule('5', ['Rules governing organizing authorities and officials', 'Правила для организаторов и судей'], ['The organisers, the committees and the race officials are bound by the rules too, in how they run and judge the event.', 'Организаторы, комитеты и судьи тоже подчиняются правилам, проводя и судя соревнование.']),
        rule('6', ['World Sailing regulations', 'Регламенты World Sailing'], ['Competitors, owners and support persons follow the World Sailing codes that count as rules: Advertising, Anti-Doping, Ethics, Eligibility and Sailor Categorization. Part 5 applies to a breach of one only if that code allows protests.', 'Гонщики, владельцы и сопровождающие лица соблюдают кодексы World Sailing со статусом правил: о рекламе, антидопинговый, этический, о допуске и о категориях гонщиков. Часть 5 применяется к их нарушению, только если сам кодекс допускает протесты.']),
      ] }] },

    { id: 'part-2', chip: t('Part 2', 'Часть 2'), title: t('Part 2 · When boats meet', 'Часть 2 · Когда лодки встречаются'),
      intro: t('These rules apply between boats sailing in or near the racing area that intend to race, are racing or have been racing. A boat not racing is penalised only for rule 14 when there is injury or serious damage, or for rule 23.1. Meeting a vessel that isn’t under these rules, a boat follows the collision regulations (IRPCAS) or the government’s right-of-way rules.', 'Эти правила действуют между лодками в районе гонки или рядом с ним, которые собираются гоняться, гоняются или уже гонялись. Лодку не в гонке наказывают только за правило 14, если есть травма или серьёзное повреждение, и за правило 23.1. Встречая судно, не идущее по этим правилам, лодка выполняет МППСС или государственные правила расхождения.'),
      sections: [
        sec('section-a', ['Section A · Right of way', 'Раздел A · Право дороги'], ['A boat has right of way when the other must keep clear of her. Sections B, C and D limit what she may do with it.', 'Лодка имеет право дороги, когда другая должна ей уступать. Разделы B, C и D ограничивают её действия.'], [
          rule('10', ['On opposite tacks', 'На разных галсах'], ['A port-tack boat keeps clear of a starboard-tack boat.', 'Лодка левого галса уступает лодке правого галса.'], '/learn/rules#r10'),
          rule('11', ['On the same tack, overlapped', 'На одном галсе, связаны'], ['A windward boat keeps clear of a leeward boat.', 'Наветренная лодка уступает подветренной.'], '/learn/rules#r11'),
          rule('12', ['On the same tack, not overlapped', 'На одном галсе, не связаны'], ['A boat clear astern keeps clear of a boat clear ahead.', 'Лодка чисто позади уступает лодке чисто впереди.'], '/learn/rules#r12'),
          rule('13', ['While tacking', 'Во время поворота оверштаг'], ['After passing head to wind a boat keeps clear of all others until she is on a close-hauled course, and rules 10, 11 and 12 don’t apply meanwhile. If two boats are tacking at once, the one on the other’s port side, or the one astern, keeps clear.', 'Пройдя положение левентик, лодка уступает всем, пока не ляжет на курс бейдевинд; правила 10, 11 и 12 в это время не действуют. Если поворачивают две лодки сразу, уступает та, что слева от другой, или та, что позади.'], '/learn/rules#r13'),
        ]),
        sec('section-b', ['Section B · General limitations', 'Раздел B · Общие ограничения'], null, [
          rule('14', ['Avoiding contact', 'Избежание контакта'], ['If reasonably possible, a boat avoids contact with another boat and doesn’t cause contact between boats, or between a boat and an object that should be avoided. A right-of-way boat, or one within the room she is owed, need act only once it is clear the other isn’t keeping clear or giving room.', 'Если это разумно возможно, лодка избегает контакта с другой лодкой и не вызывает контакта между лодками или между лодкой и предметом, которого следует избегать. Лодка с правом дороги или идущая в пределах положенного ей места должна действовать, только когда ясно, что другая не уступает или не даёт места.']),
          rule('15', ['Acquiring right of way', 'Получение права дороги'], ['A boat that gains right of way at first gives the other boat room to keep clear, unless she gained it through the other boat’s own actions.', 'Лодка, получившая право дороги, сначала даёт другой место, чтобы уступить, если только право не появилось из-за действий самой другой лодки.'], '/learn/rules#r13'),
          rule('16', ['Changing course', 'Изменение курса'], ['A right-of-way boat that changes course gives the other boat room to keep clear (16.1). On a beat, when a port-tack boat is keeping clear by heading to pass astern of a starboard-tack boat, the starboard boat must not bear away if the port boat would then have to change course at once to keep clear (16.2).', 'Лодка с правом дороги, меняя курс, даёт другой место, чтобы уступить (16.1). На лавировке, когда лодка левого галса уступает, собираясь пройти за кормой лодки правого галса, та не должна уваливаться, если из-за этого лодке левого галса придётся немедленно менять курс (16.2).'], '/learn/rules#r13'),
          rule('17', ['On the same tack; proper course', 'На одном галсе; надлежащий курс'], ['A boat that becomes overlapped from clear astern within two of her hull lengths to leeward of a boat on the same tack doesn’t sail above her proper course while they stay on that tack and overlapped within that distance, unless by doing so she promptly passes astern of the other boat.', 'Лодка, ставшая связанной из положения чисто позади ближе двух своих корпусов с подветра от лодки того же галса, не идёт выше надлежащего курса, пока они на этом галсе и связаны на таком расстоянии, если только при этом она сразу не проходит за кормой другой лодки.'], '/learn/rules#r11'),
        ]),
        sec('section-c', ['Section C · At marks and obstructions', 'Раздел C · У знаков и препятствий'], ['Section C doesn’t apply at a starting mark surrounded by navigable water, or at its anchor line, from when boats approach it to start until they have left it astern.', 'Раздел C не действует у стартового знака, окружённого судоходной водой, и у его якорного конца с момента, когда лодки подходят к нему для старта, и пока не оставят его за кормой.'], [
          rule('18.1', ['Mark-room: when rule 18 applies', 'Место у знака: когда действует правило 18'], ['When boats must leave a mark on the same side and at least one is in the zone. Not between boats on opposite tacks on a beat, on opposite tacks when only one of them has to tack at the mark, between a boat approaching a mark and one leaving it, or at a mark that is a continuing obstruction. It ends once mark-room has been given.', 'Когда лодки должны оставить знак с одной стороны и хотя бы одна из них в зоне. Не действует между лодками на разных галсах на лавировке, на разных галсах, когда у знака поворачивать надо только одной, между подходящей к знаку и отходящей от него, а также у знака, который является протяжённым препятствием. Перестаёт действовать, когда место у знака дано.'], '/learn/rules#r18'),
          rule('18.2', ['Mark-room: giving it', 'Место у знака: кто его даёт'], ['When the first of two boats reaches the zone, an outside overlapped boat gives the inside boat mark-room; if they aren’t overlapped, the boat not yet in the zone gives it to the one that is. That duty lasts even if an overlap later breaks or begins, and ends if the entitled boat passes head to wind or leaves the zone. Where there is reasonable doubt about an overlap, it is taken not to have been made or broken in time.', 'Когда первая из двух лодок входит в зону, внешняя связанная лодка даёт внутренней место у знака; если они не связаны, его даёт та, что ещё не в зоне. Обязанность сохраняется, даже если связанность потом прервётся или появится, и кончается, когда лодка, которой положено место, проходит левентик или покидает зону. При обоснованном сомнении считается, что связанность не была установлена или прервана вовремя.'], '/learn/rules#r18'),
          rule('18.3', ['Mark-room: tacking in the zone', 'Место у знака: поворот в зоне'], ['A boat that tacks from port to starboard in the zone of a mark left to port gets no mark-room from a starboard-tack boat fetching it. If that boat has been on starboard since entering the zone, the tacking boat must not make her sail above close-hauled to avoid contact, and gives her mark-room if she becomes overlapped inside.', 'Лодка, повернувшая с левого галса на правый в зоне знака, оставляемого слева, не получает места у знака от лодки правого галса, лежащей на этот знак. Если та идёт правым галсом с момента входа в зону, повернувшая не должна заставлять её идти выше бейдевинда, чтобы избежать контакта, и даёт ей место у знака, если та окажется связанной изнутри.'], '/learn/rules#r18'),
          rule('18.4', ['Mark-room: gybing in the zone', 'Место у знака: поворот фордевинд в зоне'], ['An inside overlapped right-of-way boat that must gybe at a mark to sail her proper course sails no farther from the mark than that course needs until she gybes. This doesn’t apply at a gate mark.', 'Внутренняя связанная лодка с правом дороги, которой для надлежащего курса нужно сделать у знака поворот фордевинд, до поворота уходит от знака не дальше, чем требует этот курс. У знака ворот это не действует.'], '/learn/rules#r18'),
          rule('19', ['Room to pass an obstruction', 'Место для прохода препятствия'], ['At an obstruction a right-of-way boat may choose either side, giving room to keep clear if she changes course to choose. An outside overlapped boat gives the inside boat room between her and the obstruction, unless she has been unable to from when the overlap began. At a continuing obstruction, a boat from clear astern who overlaps inside with no room to pass has no right to room and keeps clear. At a mark, rule 18 applies instead, except at a continuing obstruction.', 'Лодка с правом дороги может пройти препятствие с любой стороны, но, меняя для этого курс, даёт другой место, чтобы уступить. Внешняя связанная лодка даёт внутренней место между собой и препятствием, если только не была лишена такой возможности с начала связанности. У протяжённого препятствия лодка, вошедшая изнутри из положения чисто позади, когда места для прохода нет, права на место не имеет и уступает. У знака вместо этого действует правило 18, кроме протяжённого препятствия.']),
          rule('20', ['Room to tack at an obstruction', 'Место для поворота у препятствия'], ['A boat sailing close-hauled or above that will soon need to change course substantially to avoid an obstruction safely may hail “Room to tack” at a boat on the same tack, but not at a mark if a boat fetching it would have to change course. The hailed boat must respond, by tacking as soon as possible or by replying “You tack” and giving room; the hailing boat then tacks as soon as possible. A hailed boat may pass the hail on, and where a hail may not be heard a clear signal is added.', 'Лодка, идущая в бейдевинд или круче, которой скоро придётся существенно изменить курс, чтобы безопасно избежать препятствия, может окликнуть лодку того же галса: «Место для поворота». Нельзя окликать у знака, если из-за этого придётся менять курс лодке, лежащей на знак. Окликнутая обязана ответить: как можно скорее повернуть или ответить «Поворачивай» и дать место; окликнувшая затем поворачивает как можно скорее. Окликнутая может передать оклик дальше, а если оклик могут не услышать, добавляют ясный сигнал.']),
        ]),
        sec('section-d', ['Section D · Other rules', 'Раздел D · Другие правила'], ['When rule 21 or 22 applies between two boats, the rules of Section A do not.', 'Когда между двумя лодками действует правило 21 или 22, правила раздела A не действуют.'], [
          rule('21', ['Starting errors; taking penalties; backing a sail', 'Ошибки на старте; выполнение наказаний; парус на обратный ветер'], ['A boat going back to the pre-start side after her starting signal keeps clear of boats that aren’t, until her hull is completely on that side (21.1). A boat taking a penalty keeps clear of one that isn’t (21.2). A boat moving astern, or sideways to windward, by backing a sail keeps clear of one that isn’t (21.3).', 'Лодка, возвращающаяся на предстартовую сторону после своего стартового сигнала, уступает всем остальным, пока её корпус целиком не окажется на этой стороне (21.1). Лодка, выполняющая наказание, уступает той, что его не выполняет (21.2). Лодка, идущая назад или боком на ветер с парусом на обратный ветер, уступает той, что этого не делает (21.3).']),
          rule('22', ['Capsized, anchored or aground; rescuing', 'Перевёрнутая, на якоре, на мели; спасание'], ['If possible, a boat avoids a boat that is capsized or hasn’t regained control after capsizing, is anchored or aground, or is helping a person or vessel in danger. A boat is capsized when her masthead is in the water.', 'По возможности лодка избегает лодки, которая перевернулась или ещё не восстановила управление после этого, стоит на якоре или на мели либо помогает человеку или судну в опасности. Лодка перевёрнута, когда топ мачты в воде.']),
          rule('23', ['Interfering with another boat', 'Помеха другой лодке'], ['If reasonably possible, a boat not racing doesn’t interfere with a boat that is racing (23.1), and no boat interferes with one taking a penalty, sailing another leg or returning under rule 21.1. After the starting signal this second part doesn’t bind a boat sailing her proper course (23.2).', 'Если это разумно возможно, лодка не в гонке не мешает лодке в гонке (23.1), и никакая лодка не мешает той, что выполняет наказание, идёт по другому отрезку дистанции или возвращается по правилу 21.1. После стартового сигнала эта вторая часть не связывает лодку, идущую надлежащим курсом (23.2).']),
        ]),
      ] },

    { id: 'part-3', chip: t('Part 3', 'Часть 3'), title: t('Part 3 · Conduct of a race', 'Часть 3 · Проведение гонки'),
      intro: t('How the race committee starts, shortens, changes and ends a race, and what each signal asks of you.', 'Как гоночный комитет стартует, сокращает, меняет и завершает гонку и чего требует каждый сигнал.'),
      sections: [{ entries: [
        rule('25', ['Notice of race, sailing instructions and signals', 'Положение, гоночная инструкция и сигналы'], ['The notice of race is available before a boat enters and the sailing instructions before a race begins. The meanings of the race signals are fixed, and any other signal must be explained in those documents. An object that looks like the flag may stand in for it.', 'Положение о соревновании доступно до подачи заявки, гоночная инструкция — до начала гонки. Значения гоночных сигналов неизменны, а любые другие сигналы объясняются в этих документах. Флаг можно заменить похожим на него предметом.']),
        rule('26', ['Starting races', 'Старт гонки'], ['The usual countdown: class flag up at 5 minutes with one sound (warning); P, I, Z, Z with I, U or the black flag up at 4 with one sound (preparatory); that flag down at 1 with one long sound; class flag down at 0 with one sound (start). Time is taken from the flags, so a missed sound doesn’t count.', 'Обычный отсчёт: за 5 минут поднят флаг класса, один звук (предупреждение); за 4 — флаг P, I, Z, Z с I, U или чёрный, один звук (подготовительный сигнал); за 1 — этот флаг спущен, один длинный звук; в 0 — флаг класса спущен, один звук (старт). Время считают по флагам, поэтому пропущенный звук не важен.'], '/learn/start'),
        rule('27', ['Other race committee actions before the starting signal', 'Другие действия комитета до старта'], ['By the warning signal the committee signals the course if the sailing instructions haven’t set it, and may require personal flotation devices with flag Y. By the preparatory signal it may move a starting mark. Before the start it may postpone or abandon the race for any reason.', 'Не позже предупреждения комитет обозначает дистанцию, если её нет в инструкции, и может флагом Y потребовать надеть жилеты. Не позже подготовительного сигнала может передвинуть стартовый знак. До старта может отложить или прекратить гонку по любой причине.']),
        rule('28', ['Sailing the course', 'Прохождение дистанции'], ['A boat sails the course, and may correct any mistake in it as long as she hasn’t finished.', 'Лодка проходит дистанцию и может исправить любую ошибку, пока не финишировала.']),
        rule('29', ['Recalls', 'Отзывы'], ['Individual recall: flag X with one sound when a boat is on the course side at her start or must comply with rule 30.1, flown until they are all back, but no later than four minutes after the start or one minute before a later start, whichever comes first. General recall: the First Substitute with two sounds when the boats can’t be identified or the procedure went wrong; the new warning comes one minute after it is lowered.', 'Индивидуальный отзыв: флаг X с одним звуком, если лодка в момент старта на стороне дистанции или должна выполнить правило 30.1; он поднят, пока все не вернутся, но не дольше четырёх минут после старта или до минуты перед следующим стартом — что раньше. Общий отзыв: Первый заменяющий с двумя звуками, если лодки нельзя опознать или в процедуре была ошибка; новое предупреждение — через минуту после спуска флага.']),
        rule('30', ['Starting penalties', 'Наказания на старте'], ['Flag I: a boat on the course side in the last minute must go round an end of the line to the pre-start side before she starts. In the last minute, under flags Z, U and black, no part of the hull may be in the triangle of the line’s ends and the first mark. Z: a 20% scoring penalty, even if the race is restarted. U: disqualified without a hearing, unless the race is restarted or resailed. Black: disqualified without a hearing even then, and she may not sail the restart.', 'Флаг I: лодка на стороне дистанции в последнюю минуту должна вернуться на предстартовую сторону через продолжение линии, прежде чем стартовать. В последнюю минуту при флагах Z, U и чёрном ни одна часть корпуса не должна быть в треугольнике из концов линии и первого знака. Z: штраф 20% очков, даже если гонку перестартуют. U: дисквалификация без рассмотрения, если гонку не перестартуют и не проведут заново. Чёрный: дисквалификация без рассмотрения даже в этом случае, и в новом старте лодка участвовать не может.']),
        rule('31', ['Touching a mark', 'Касание знака'], ['While racing, a boat doesn’t touch a starting mark before starting, a mark that begins, bounds or ends the leg she is on, or a finishing mark after finishing.', 'В гонке лодка не касается стартового знака до старта, знака, который начинает, ограничивает или заканчивает её отрезок дистанции, и финишного знака после финиша.'], '/learn/rules#pen'),
        rule('32', ['Shortening or abandoning after the start', 'Сокращение или прекращение после старта'], ['After the start the committee may shorten or abandon for foul weather, too little wind to finish in the time limit, a mark missing or out of position, or anything directly affecting safety or fairness. It may also shorten so other races can be sailed, or abandon for an error in the starting procedure. Shorten: flag S with two sounds. Abandon: N, N over H or N over A with three sounds.', 'После старта комитет может сократить или прекратить гонку из-за плохой погоды, слабого ветра, когда никто не успеет за контрольное время, пропажи или смещения знака и всего, что прямо влияет на безопасность или честность. Может также сократить, чтобы провести другие гонки, или прекратить из-за ошибки в процедуре старта. Сокращение: флаг S, два звука. Прекращение: N, N над H или N над A, три звука.']),
        rule('33', ['Changing the next leg of the course', 'Изменение следующего отрезка'], ['At a rounding mark or a gate the committee may change the next leg by moving the next mark or the finishing line, signalling before boats begin the leg: flag C with repetitive sounds and the new bearing, a green triangle for starboard, a red rectangle for port, or “–” or “+” for a shorter or longer leg.', 'У знака огибания или ворот комитет может изменить следующий отрезок, передвинув следующий знак или финишную линию, и подаёт сигнал до начала этого отрезка: флаг C с повторяющимися звуками и новый пеленг, зелёный треугольник — вправо, красный прямоугольник — влево, либо «–» или «+» — короче или длиннее.']),
        rule('34', ['Mark missing', 'Пропавший знак'], ['If a mark is missing or out of position the committee, if possible, puts it back or replaces it with a similar one, or with an object showing flag M and repetitive sounds.', 'Если знак пропал или смещён, комитет по возможности возвращает его на место, заменяет похожим либо предметом с флагом M и подаёт повторяющиеся звуки.']),
        rule('35', ['Race time limit and scores', 'Контрольное время и очки'], ['If one boat sails the course within any time limit, every boat that finishes is scored by her place unless the race is abandoned. If none does, the committee abandons the race.', 'Если хотя бы одна лодка прошла дистанцию в контрольное время, все финишировавшие получают очки по местам, если гонка не прекращена. Если никто не успел, комитет прекращает гонку.']),
        rule('36', ['Races restarted or resailed', 'Новый старт или повторная гонка'], ['A breach in the original race doesn’t stop a boat sailing the restart or resail unless she broke rule 30.4, and penalises her only under rule 2, 30.2, 30.4 or 69, or rule 14 if she caused injury or serious damage.', 'Нарушение в первоначальной гонке не мешает участвовать в новом старте или повторной гонке, кроме нарушения правила 30.4, и наказывается только по правилам 2, 30.2, 30.4 или 69 либо по правилу 14, если лодка причинила травму или серьёзное повреждение.']),
        rule('37', ['Search and rescue instructions', 'Поисково-спасательные указания'], ['At flag V with one sound, all boats and official and support vessels monitor the race committee’s channel, if they can, for search and rescue instructions.', 'При флаге V с одним звуком все лодки и суда обеспечения по возможности слушают канал гоночного комитета для получения поисково-спасательных указаний.']),
      ] }] },

    { id: 'part-4', chip: t('Part 4', 'Часть 4'), title: t('Part 4 · Other requirements when racing', 'Часть 4 · Другие требования в гонке'),
      intro: t('What a boat and her crew may and may not do while racing, unless a rule says otherwise.', 'Что можно и чего нельзя лодке и экипажу во время гонки, если правило не говорит иного.'),
      sections: [
        sec('section-4a', ['Section A · General requirements', 'Раздел A · Общие требования'], null, [
          rule('40', ['Personal flotation devices', 'Спасательные жилеты'], ['Everyone wears one, except briefly while changing clothing or personal gear, when flag Y is shown with one sound (afloat by the warning signal, for that race; ashore, for all the time afloat that day) or when a rule says so. A wetsuit or drysuit doesn’t count.', 'Все носят жилет, кроме коротких моментов смены одежды или снаряжения, когда поднят флаг Y с одним звуком (на воде не позже предупреждения — на эту гонку; на берегу — на всё время на воде в этот день) или когда этого требует правило. Гидрокостюм и сухой костюм жилетом не считаются.']),
          rule('41', ['Outside help', 'Посторонняя помощь'], ['A boat takes no outside help, except for a crew member who is ill, injured or in danger; from the other vessel’s crew to get clear after a collision; information freely available to all boats; and unasked-for information from a disinterested source, which may be another boat in the same race.', 'Лодка не получает посторонней помощи, кроме помощи заболевшему, травмированному или находящемуся в опасности члену экипажа; помощи экипажа другого судна, чтобы разойтись после столкновения; сведений, доступных всем лодкам; и незапрошенных сведений от незаинтересованного источника, которым может быть другая лодка этой же гонки.']),
          rule('42', ['Propulsion', 'Движущая сила'], ['A boat uses only the wind and the water to change her speed. Banned: pumping, rocking, ooching, sculling, and repeated tacks or gybes unrelated to wind shifts or tactics (42.2). Allowed, among others: rolling to help steer, one pull of each sail per wave or gust to start surfing or planing, any number of pulls to start foiling, sculling to turn to close-hauled when stopped or slow above that course, and any means to help someone in danger (42.3).', 'Лодка меняет скорость только за счёт ветра и воды. Запрещены пампинг, рокинг, учинг, скаллинг и повторные повороты, не связанные со сдвигами ветра или тактикой (42.2). Разрешены, среди прочего: крен для управления, один рывок каждым парусом на волну или порыв, чтобы начать сёрфинг или глиссирование, любое число рывков для выхода на крылья, скаллинг для ухода на бейдевинд, когда лодка стоит или медленно идёт круче него, и любые средства, чтобы помочь тому, кто в опасности (42.3).']),
          rule('43', ['Exoneration', 'Освобождение от ответственности'], ['A boat forced to break a rule by another boat’s breach is exonerated. So is one that, sailing within the room or mark-room she is owed, breaks a Section A rule or rule 15, 16 or 31 because of an incident with the boat that owes it, and a right-of-way boat or one within her room that breaks rule 14 with no damage or injury. An exonerated boat takes no penalty.', 'Лодка, вынужденная нарушить правило из-за нарушения другой, освобождается от ответственности. Так же и лодка, которая в пределах положенного ей места нарушила правило раздела A или правила 15, 16 или 31 из-за инцидента с лодкой, обязанной это место дать, и лодка с правом дороги или в пределах своего места, нарушившая правило 14 без повреждений и травм. Освобождённая лодка наказание не выполняет.'], '/learn/rules#pen'),
          rule('44', ['Penalties at the time of an incident', 'Наказания в момент инцидента'], ['Two turns for a Part 2 rule, one for rule 31, unless the notice of race or sailing instructions set another penalty; for both in one incident, only the Part 2 penalty. Get well clear as soon as possible, then promptly turn the same way, each turn with one tack and one gybe. If she caused injury or serious damage, or gained a significant advantage despite the penalty, she must retire. A scoring penalty, where used, means showing a yellow flag and losing the stated points, or 20% of the Did Not Finish score.', 'Два оборота за нарушение части 2, один — за правило 31, если положение или инструкция не устанавливают иное наказание; за оба в одном инциденте — только наказание по части 2. Как можно скорее отойдите от других лодок и сразу крутитесь в одну сторону, каждый оборот — один поворот оверштаг и один фордевинд. Если лодка причинила травму или серьёзное повреждение либо несмотря на наказание получила существенное преимущество, она выходит из гонки. Штраф очками, если он применяется: жёлтый флаг и потеря указанных очков или 20% от очков за «не финишировала».'], '/learn/rules#pen'),
          rule('45', ['Hauling out; making fast; anchoring', 'Подъём из воды; швартовка; якорь'], ['A boat is afloat and off moorings at her preparatory signal. After that she isn’t hauled out or made fast except to bail, reef or repair. She may anchor or the crew may stand on the bottom, but she recovers the anchor before going on unless she can’t.', 'К подготовительному сигналу лодка на плаву и не на швартовах. После этого её не поднимают из воды и не швартуют, кроме как для откачки воды, взятия рифов или ремонта. Она может стать на якорь, а экипаж — стоять на дне, но якорь нужно поднять, прежде чем продолжить гонку, если это возможно.']),
          rule('46', ['Person in charge', 'Ответственный на лодке'], ['Each boat has on board a person in charge, named by the member or organisation that entered her.', 'На каждой лодке есть ответственный, назначенный членом клуба или организацией, заявившими лодку.']),
          rule('47', ['Trash disposal', 'Мусор'], ['Competitors and support persons never intentionally put trash in the water, at any time while afloat. The penalty may be less than disqualification.', 'Гонщики и сопровождающие лица никогда намеренно не выбрасывают мусор в воду, всё время пока находятся на воде. Наказание может быть мягче дисквалификации.']),
        ]),
        sec('section-4b', ['Section B · Equipment-related requirements', 'Раздел B · Требования к снаряжению'], null, [
          rule('48', ['Limitations on equipment and crew', 'Ограничения на снаряжение и экипаж'], ['A boat uses only the equipment on board at her preparatory signal. Nobody leaves on purpose except when ill or injured, to help someone in danger, or to swim, and anyone off the boat must be back in contact with her before she sails on to the next mark.', 'Лодка использует только снаряжение, бывшее на борту к подготовительному сигналу. Никто намеренно не покидает лодку, кроме случаев болезни, травмы, помощи тем, кто в опасности, или купания; оказавшийся за бортом должен снова коснуться лодки, прежде чем она продолжит идти к следующему знаку.']),
          rule('49', ['Crew position; lifelines', 'Положение экипажа; леера'], ['No device holds the body outboard, other than hiking straps and stiffeners under the thighs. Where lifelines are required, the torso stays inside them except briefly for a necessary task, with an allowance for sitting out on boats with upper and lower lifelines, and lifelines are taut unless a rule says otherwise.', 'Никаких приспособлений для выноса тела за борт, кроме откренивающих ремней и жёстких вставок под бёдрами. Где леера обязательны, туловище остаётся внутри них, кроме коротких необходимых работ, с оговоркой для сидящих на лодках с верхним и нижним леером; леера натянуты, если правило не говорит иного.']),
          rule('50', ['Competitor clothing and equipment', 'Одежда и снаряжение гонщика'], ['Nothing is worn or carried to add weight. Clothing and equipment weigh no more than 8 kg, unless class rules or the notice of race set a lower limit or a higher one up to 10 kg, not counting a crew harness and what is worn below the knee. A harness floats, weighs up to 2 kg (4 kg if class rules allow) and releases easily. These limits don’t apply to boats that must have lifelines.', 'Ничего не надевают и не носят ради увеличения веса. Одежда и снаряжение весят не больше 8 кг, если правила класса или положение не установили меньший предел либо больший до 10 кг, не считая трапециевой обвязки и того, что носят ниже колена. Обвязка плавучая, весит до 2 кг (до 4 кг, если позволяют правила класса) и легко отсоединяется. На лодки, которым положены леера, эти пределы не распространяются.']),
          rule('51', ['Movable ballast', 'Подвижный балласт'], ['All movable ballast, unset sails included, is properly stowed. Water, dead weight or ballast isn’t moved to change trim or stability. Floorboards, bulkheads, doors, stairs and water tanks stay in place and cabin fixtures on board. Bilge water may be bailed out.', 'Весь подвижный балласт, включая неподнятые паруса, надёжно закреплён. Воду, грузы и балласт не перемещают для изменения дифферента или остойчивости. Пайолы, переборки, двери, трапы и цистерны остаются на месте, оборудование каюты — на борту. Трюмную воду можно откачивать.']),
          rule('52', ['Manual power', 'Ручная сила'], ['Rigging, spars and movable hull appendages are adjusted and worked only by the crew’s own power.', 'Такелаж, рангоут и подвижные выступающие части работают только от силы экипажа.']),
          rule('53', ['Skin friction', 'Поверхностное трение'], ['A boat doesn’t release polymers or similar substances, or have specially textured surfaces, that could improve the flow of water in the boundary layer.', 'Лодка не выпускает полимеры и подобные вещества и не имеет особых текстурированных поверхностей, способных улучшить обтекание в пограничном слое.']),
          rule('54', ['Forestays and headsail tacks', 'Штаги и галсовые углы передних парусов'], ['Forestays and headsail tacks are attached about on the centreline, except a spinnaker staysail’s when the boat isn’t close-hauled.', 'Штаги и галсовые углы передних парусов крепятся примерно на диаметральной плоскости, кроме спинакер-стакселя, когда лодка идёт не в бейдевинд.']),
          rule('55', ['Setting and sheeting sails', 'Постановка парусов и шкоты'], ['A new headsail or spinnaker may be set and trimmed before the old one comes down, but only one mainsail and, except when changing, one spinnaker are set at a time. One spinnaker or whisker pole is used at a time except when gybing, attached to the foremost mast. No sail is sheeted over a device that pushes the sheet or clew outboard of the hull or deck, with a few listed exceptions.', 'Новый передний парус или спинакер можно поставить и настроить до уборки старого, но поднят только один грот и, кроме момента замены, один спинакер. Используется один спинакер-гик или выстрел, кроме момента поворота фордевинд, закреплённый на передней мачте. Парус не проводят через устройство, выносящее шкот или шкотовый угол за пределы корпуса или палубы, кроме нескольких перечисленных исключений.']),
          rule('56', ['Fog signals and lights; traffic separation schemes; tracking systems', 'Туманные сигналы и огни; системы разделения движения; трекинг'], ['When equipped, a boat sounds fog signals and shows lights as the collision regulations or government rules require, and follows rule 10 of the collision regulations on traffic separation schemes. A required AIS or tracking device is never switched off or deliberately made less effective.', 'Если есть оборудование, лодка подаёт туманные сигналы и несёт огни по МППСС или государственным правилам и соблюдает правило 10 МППСС о системах разделения движения. Обязательный АИС или трекер нельзя отключать или намеренно ухудшать его работу.']),
        ]),
      ] },

    { id: 'part-5', chip: t('Part 5', 'Часть 5'), title: t('Part 5 · Protests, redress, hearings, misconduct and appeals', 'Часть 5 · Протесты, исправление результата, рассмотрения, проступки и апелляции'),
      intro: t('What happens after the race when boats disagree, when a boat was wronged, or when someone behaves badly.', 'Что происходит после гонки, когда лодки не согласны друг с другом, когда лодку обидели или кто-то повёл себя недостойно.'),
      sections: [
        sec('section-5a', ['Section A · Protests; redress; support persons', 'Раздел A · Протесты; исправление результата; сопровождающие лица'], null, [
          rule('60', ['Protests', 'Протесты'], ['A boat or a committee may protest a boat. A boat hails “Protest” at the first reasonable opportunity and, if longer than 6 metres, also flies a red flag until she stops racing. The written protest reaches the race office within two hours of the last boat finishing, unless the sailing instructions say otherwise. A protest about Part 2 or rule 31 is valid only from a boat that was involved and saw the incident. A boat found to have broken a rule is disqualified, unless she is exonerated, has already taken a penalty or another penalty applies.', 'Лодка или комитет могут опротестовать лодку. Лодка окликает «Протест» при первой разумной возможности и, если длиннее 6 метров, ещё поднимает красный флаг до конца гонки. Письменный протест подают в офис гонки в течение двух часов после финиша последней лодки, если инструкция не говорит иного. Протест по части 2 или правилу 31 действителен только от лодки, которая участвовала в инциденте и видела его. Лодку, признанную нарушившей правило, дисквалифицируют, если она не освобождена от ответственности, не выполнила наказание и к ней не применяется другое наказание.']),
          rule('61', ['Redress', 'Исправление результата'], ['A boat is entitled to redress when her score is made significantly worse, through no fault of her own, by an improper action or omission of a committee or the organisers, by injury or damage from a boat breaking Part 2 or a vessel that should have kept clear, by giving help under rule 1.1, or by another boat’s action that led to a penalty under rule 2 or a penalty or warning under rule 69. She asks in writing, generally within the protest time limit, and the protest committee makes as fair an arrangement as it can for all boats affected.', 'Лодка имеет право на исправление результата, если её очки существенно ухудшились не по её вине: из-за неправильного действия или бездействия комитета либо организатора, травмы или повреждения от лодки, нарушившей часть 2, или судна, обязанного уступать, из-за помощи по правилу 1.1 либо из-за действий другой лодки, за которые назначено наказание по правилу 2 или наказание либо предупреждение по правилу 69. Запрос подают письменно, как правило в срок подачи протеста, а протестовый комитет принимает самое справедливое решение для всех затронутых лодок.']),
          rule('62', ['Support persons', 'Сопровождающие лица'], ['The protest committee may hear whether a support person broke a rule. It may warn them, exclude them from the event or venue or take other action, and may change the score of a boat that gained an advantage from the breach, up to disqualification in one race.', 'Протестовый комитет может рассмотреть, нарушило ли сопровождающее лицо правило. Он может вынести предупреждение, отстранить от соревнования или места его проведения либо принять другие меры и изменить очки лодки, получившей преимущество от нарушения, вплоть до дисквалификации в одной гонке.']),
        ]),
        sec('section-5b', ['Section B · Hearings and making decisions', 'Раздел B · Рассмотрения и решения'], null, [
          rule('63', ['Conduct of hearings', 'Проведение рассмотрений'], ['Parties are told the time and place, see the papers, get reasonable time to prepare, may have a representative and may question anyone giving evidence. A committee member with a conflict of interest stands aside unless the parties consent or it isn’t significant. The committee first decides validity, then takes evidence, finds the facts on the balance of probabilities and decides by majority. A party may ask for the decision in writing within seven days, and for a reopening within 24 hours of being told of it, or sooner on the last day of racing.', 'Стороны узнают время и место, знакомятся с документами, получают разумное время на подготовку, могут иметь представителя и задавать вопросы всем, кто даёт показания. Член комитета с конфликтом интересов отстраняется, если стороны не согласны или конфликт существенный. Комитет сначала решает вопрос о действительности, затем заслушивает показания, устанавливает факты по балансу вероятностей и решает большинством голосов. Сторона может запросить решение письменно в течение семи дней и попросить о повторном рассмотрении в течение 24 часов после объявления решения, а в последний день гонок — раньше.']),
          rule('64', ['Discretionary penalties', 'Дискреционные наказания'], ['When a boat reports within the protest time limit that she broke a rule open to a discretionary penalty, the protest committee sets the penalty after considering the evidence. No hearing is needed.', 'Если лодка в срок подачи протеста сообщает, что нарушила правило с дискреционным наказанием, протестовый комитет назначает наказание, изучив доказательства. Рассмотрение не требуется.']),
          rule('65', ['Legal liability and costs', 'Юридическая ответственность и расходы'], ['Legal liability and claims for damages are left to national prescriptions. The unsuccessful party pays measurement costs in a protest about a class rule, unless the protest committee decides otherwise.', 'Вопросы юридической ответственности и возмещения ущерба решаются предписаниями национальной федерации. Расходы на обмер при протесте по правилам класса оплачивает проигравшая сторона, если протестовый комитет не решит иначе.']),
        ]),
        sec('section-5c', ['Section C · Misconduct', 'Раздел C · Проступки'], null, [
          rule('69', ['Misconduct', 'Проступок'], ['Conduct that breaches good manners, sportsmanship or ethics, or may bring the sport into disrepute. An allegation isn’t grounds for a protest: a protest committee of at least three may investigate and hold a hearing, and may warn, change scores, disqualify or exclude a person from the event, and report to the national authority or World Sailing, which may add further penalties, including suspension.', 'Поведение, нарушающее правила приличия, спортивные или этические нормы либо способное опорочить спорт. Обвинение не основание для протеста: протестовый комитет не менее чем из трёх человек может провести расследование и рассмотрение, вынести предупреждение, изменить очки, дисквалифицировать или отстранить от соревнования и сообщить национальной федерации или World Sailing, а те могут добавить наказания вплоть до отстранения от спорта.']),
        ]),
        sec('section-5d', ['Section D · Appeals', 'Раздел D · Апелляции'], null, [
          rule('70', ['Appeals and requests to a national authority', 'Апелляции и запросы в национальную федерацию'], ['A party may appeal a protest committee’s decision or procedures, but not the facts found, to the national authority, and may also appeal a failure to hold a hearing or decide. There is no appeal from a properly constituted international jury, or in a few other cases if the notice of race or sailing instructions say so. A protest committee may ask the national authority to confirm or correct its decision.', 'Сторона может обжаловать решение или процедуру протестового комитета в национальной федерации, но не установленные факты; обжаловать можно и отказ провести рассмотрение или принять решение. Решения должным образом сформированного международного жюри и в ряде других случаев, указанных в положении или инструкции, не обжалуются. Протестовый комитет может попросить федерацию подтвердить или исправить его решение.']),
          rule('71', ['National authority decisions', 'Решения национальной федерации'], ['The national authority accepts the facts found unless rule R5 applies. It may uphold, change or reverse the decision, or order a hearing reopened or held anew. Anyone with a conflict of interest, or who sat on the protest committee, takes no part. Its decision is final.', 'Федерация принимает установленные факты, если не применяется правило R5. Она может оставить решение в силе, изменить или отменить его либо назначить повторное или новое рассмотрение. Люди с конфликтом интересов и члены того протестового комитета не участвуют. Её решение окончательно.']),
          rule('72', ['Interpretations', 'Толкования'], ['A club or other affiliated organisation may ask the national authority to interpret the rules, as long as no appealable protest committee decision is involved. An interpretation doesn’t change an earlier decision.', 'Клуб или другая аффилированная организация может запросить у федерации толкование правил, если дело не касается решения протестового комитета, которое можно обжаловать. Толкование не меняет прежнее решение.']),
        ]),
      ] },

    { id: 'part-6', chip: t('Part 6', 'Часть 6'), title: t('Part 6 · Entry and qualification', 'Часть 6 · Заявка и допуск'),
      intro: t('Who may enter an event, and what a boat must have in order.', 'Кто может заявиться на соревнование и что должно быть в порядке у лодки.'),
      sections: [{ entries: [
        rule('75', ['Entering an event', 'Заявка на соревнование'], ['A boat meets the organisers’ requirements and is entered by a member of a club or organisation affiliated to a World Sailing member national authority, by such a club or organisation, or by a member of that national authority.', 'Лодка выполняет требования организатора, и её заявляет член клуба или организации, входящей в национальную федерацию — члена World Sailing, сам такой клуб или организация либо член этой федерации.']),
        rule('76', ['Exclusion of boats or competitors', 'Отказ в участии'], ['The organisers or the race committee may reject an entry or exclude a competitor before the first race, for a proper reason given in writing on request. They may not do so because of advertising that meets the code or, at world and continental championships, for an entry within stated quotas without the class’s or World Sailing’s approval. A boat that thinks the decision improper may ask for redress.', 'Организатор или гоночный комитет могут отклонить заявку или отстранить гонщика до первой гонки по обоснованной причине, сообщаемой письменно по запросу. Нельзя делать это из-за рекламы, соответствующей кодексу, а на чемпионатах мира и континентов — без согласия класса или World Sailing, если заявка в пределах квот. Считающая отказ неправильным лодка может запросить исправление результата.']),
        rule('77', ['Identification on sails', 'Опознавательные знаки на парусах'], ['A boat carries class insignia, national letters and numbers on her sails as Appendix G requires.', 'На парусах лодки — эмблема класса, национальные буквы и номера по приложению G.']),
        rule('78', ['Compliance with class rules; certificates', 'Соответствие правилам класса; сертификаты'], ['While racing, the owner and the person in charge keep the boat within her class rules and her certificate valid. If a required certificate can’t be shown, she may race on a signed statement that one exists, and must produce it before the last day of the event or of the first series, whichever is earlier, or be disqualified from all races.', 'Во время гонки владелец и ответственный следят, чтобы лодка соответствовала правилам класса, а сертификат был действителен. Если нужный сертификат нельзя предъявить, лодка может гоняться по подписанному заявлению о том, что он есть, и должна предъявить его до последнего дня соревнования или первой серии — что раньше, иначе её дисквалифицируют во всех гонках.']),
        rule('79', ['Categorization', 'Категории гонщиков'], ['If the notice of race or class rules require sailor categories, they are given under the World Sailing Sailor Categorization Code.', 'Если положение или правила класса требуют категории гонщиков, их присваивают по кодексу World Sailing о категориях.']),
        rule('80', ['Rescheduled event', 'Перенос соревнования'], ['If an event moves to new dates, all entered boats are told, and the race committee may accept new entries that meet every requirement but the original deadline.', 'Если соревнование переносят на другие даты, всем заявленным лодкам сообщают об этом, а гоночный комитет может принять новые заявки, отвечающие всем требованиям, кроме прежнего срока.']),
      ] }] },

    { id: 'part-7', chip: t('Part 7', 'Часть 7'), title: t('Part 7 · Event organization', 'Часть 7 · Организация соревнования'),
      intro: t('Who runs an event, who judges it and how its rules may be changed.', 'Кто проводит соревнование, кто его судит и как можно менять его правила.'),
      sections: [{ entries: [
        rule('85', ['Changes to rules', 'Изменения правил'], ['A change must name the rule and state the change, whether it adds to the rule, deletes from it or alters it. Each kind of rule can be changed only by the route set for it.', 'Изменение должно назвать правило и указать, что меняется: что добавлено, удалено или изменено. Каждый вид правил меняют только установленным для него способом.']),
        rule('86', ['Changes to the racing rules', 'Изменения гоночных правил'], ['National prescriptions may change a racing rule, but not the Definitions, Part 2, Part 7 or a list of protected rules. The notice of race or sailing instructions may change a rule too, but not those or rules 4, 76.1, 76.2(a) and Appendix R. Class rules may change only rules 42, 49, 51 to 55 and 78.2.', 'Предписания национальной федерации могут менять гоночные правила, но не определения, части 2 и 7 и перечень защищённых правил. Положение или инструкция тоже могут менять правила, но не эти и не правила 4, 76.1, 76.2(a) и приложение R. Правила класса могут менять только правила 42, 49, 51–55 и 78.2.']),
        rule('87', ['Changes to class rules', 'Изменения правил класса'], ['The notice of race may change a class rule only if the class rules allow it or the class association’s written permission is posted on the official notice board.', 'Положение может изменить правило класса, только если это позволяют правила класса или на официальной доске вывешено письменное разрешение классовой ассоциации.']),
        rule('88', ['National prescriptions', 'Предписания национальной федерации'], ['The prescriptions that apply are those of the national authority the organisers are associated with. The notice of race or sailing instructions may change them, unless that authority has restricted this with World Sailing’s approval.', 'Действуют предписания федерации, с которой связан организатор. Положение или инструкция могут их менять, если федерация с одобрения World Sailing этого не ограничила.']),
        rule('89', ['Organizing authority; notice of race; appointment of race officials', 'Организатор; положение; назначение судей'], ['An event is organised by World Sailing, a national authority, an affiliated club or organisation, or a class association or other body on set conditions. The organisers publish the notice of race and appoint the race committee and, when appropriate, protest and technical committees and umpires.', 'Соревнование организует World Sailing, национальная федерация, аффилированный клуб или организация либо классовая ассоциация или другой орган на установленных условиях. Организатор публикует положение и назначает гоночный комитет, а при необходимости протестовый и технический комитеты и ампайров.']),
        rule('90', ['Race committee; sailing instructions; scoring', 'Гоночный комитет; инструкция; подсчёт очков'], ['The race committee runs the races as directed and as the rules require, publishes the sailing instructions and scores by Appendix A unless another system is set. A race is scored if it isn’t abandoned and one boat sails the course within any time limit, and scoring errors it finds are corrected.', 'Гоночный комитет проводит гонки по указаниям организатора и правилам, публикует гоночную инструкцию и считает очки по приложению A, если не установлена другая система. Гонка идёт в зачёт, если не прекращена и хотя бы одна лодка прошла дистанцию в контрольное время; найденные ошибки подсчёта исправляются.']),
        rule('91', ['Protest committee', 'Протестовый комитет'], ['A committee appointed by the organisers or the race committee, an international jury, or a committee appointed by the national authority under rule 71.3(c).', 'Комитет, назначенный организатором или гоночным комитетом, международное жюри либо комитет, назначенный национальной федерацией по правилу 71.3(c).']),
        rule('92', ['Technical committee', 'Технический комитет'], ['At least one member, appointed by the organisers, the race committee or as World Sailing regulations prescribe. It carries out equipment inspection and event measurement.', 'Не меньше одного человека, назначенного организатором, гоночным комитетом или по регламентам World Sailing. Проводит проверку снаряжения и обмер на соревновании.']),
      ] }] },

    { id: 'appendices', chip: t('Appendices', 'Приложения'), title: t('Appendices', 'Приложения'),
      intro: t('Rules for particular kinds of racing and procedures. An appendix that applies takes precedence over any part of the rules it conflicts with.', 'Правила для отдельных видов гонок и процедур. Действующее приложение важнее части правил, с которой расходится.'),
      sections: [{ entries: [
        app('A', ['Scoring', 'Подсчёт очков'], ['The Low Point System: first place scores 1, second 2 and so on, a boat’s worst race is excluded unless the notice of race says otherwise, and the lowest total wins. A boat that didn’t sail the course, retired or was disqualified scores one more than the number of boats entered. Ties go to the better scores, then to the last race. The codes: DNC, DNS, OCS, ZFP, UFD, BFD, SCP, NSC, DNF, RET, DSQ, DNE, RDG and DPI.', 'Линейная система: за первое место 1 очко, за второе 2 и так далее, худшая гонка отбрасывается, если положение не говорит иного, побеждает наименьшая сумма. Лодка, не прошедшая дистанцию, вышедшая из гонки или дисквалифицированная, получает на одно очко больше числа заявленных лодок. При равенстве решают лучшие результаты, затем последняя гонка. Обозначения: DNC, DNS, OCS, ZFP, UFD, BFD, SCP, NSC, DNF, RET, DSQ, DNE, RDG и DPI.']),
        app('B', ['Windsurfing fleet racing rules', 'Правила флотовых гонок на виндсёрфинге'], ['How the rules change for windsurfing fleet races, marathon races included.', 'Как меняются правила для флотовых гонок на виндсёрфинге, включая марафоны.']),
        app('C', ['Match racing rules', 'Правила матчевых гонок'], ['How the rules change for match races, which are umpired unless the notice of race or sailing instructions say otherwise.', 'Как меняются правила для матчевых гонок, которые судят ампайры, если положение или инструкция не говорят иного.']),
        app('D', ['Team racing rules', 'Правила командных гонок'], ['How the rules change for team races. Among other things, the zone shrinks to two hull lengths.', 'Как меняются правила для командных гонок. Среди прочего, зона уменьшается до двух корпусов.']),
        app('E', ['Radio sailing racing rules', 'Правила гонок радиоуправляемых яхт'], ['How the rules change for radio-controlled boats. Among other things, the zone grows to four hull lengths.', 'Как меняются правила для радиоуправляемых яхт. Среди прочего, зона увеличивается до четырёх корпусов.']),
        app('F', ['Kiteboarding racing rules', 'Правила гонок на кайтборде'], ['How the rules and definitions change for kiteboard course races.', 'Как меняются правила и определения для гонок на кайтборде.']),
        app('G', ['Identification on sails', 'Опознавательные знаки на парусах'], ['The class insignia, national letters and sail numbers a boat carries, and where and how large they go.', 'Какие эмблема класса, национальные буквы и номера несёт лодка, где они расположены и какого размера.']),
        app('H', ['Weighing clothing and equipment', 'Взвешивание одежды и снаряжения'], ['How rule 50 is checked: the items are soaked in fresh water, drained on a rack for one minute and weighed.', 'Как проверяют правило 50: вещи замачивают в пресной воде, дают стечь на вешалке одну минуту и взвешивают.']),
        app('J', ['Notice of race and sailing instructions', 'Положение и гоночная инструкция'], ['What these two documents must contain and what they may.', 'Что эти два документа обязаны содержать и что могут.']),
        app('M', ['Recommendations for protest committees', 'Рекомендации протестовым комитетам'], ['Advice, not requirements, on running a fair hearing from the first papers to the decision.', 'Советы, а не требования, как честно провести рассмотрение от первых документов до решения.']),
        app('N', ['International juries', 'Международные жюри'], ['At least five experienced members, most of them International Judges, and no more than two from one national authority (three in Groups M, N and Q). There is no appeal from their decisions.', 'Не меньше пяти опытных членов, большинство — международные судьи, не больше двух от одной федерации (трёх в группах M, N и Q). Их решения не обжалуются.']),
        app('P', ['Special procedures for rule 42', 'Особые процедуры по правилу 42'], ['Applies only if the event says so. Observers penalise a breach on the water with a sound signal and a yellow flag. First time, a Two-Turns Penalty; second time, she retires; a third time, she retires and the disqualification can’t be excluded.', 'Действует, только если это указано для соревнования. Наблюдатели наказывают прямо на воде звуковым сигналом и жёлтым флагом. В первый раз — два оборота, во второй — выход из гонки, в третий — выход из гонки и дисквалификация, которую нельзя исключить из зачёта.']),
        app('R', ['Procedures for appeals and requests', 'Процедура апелляций и запросов'], ['How to appeal to a national authority: the appeal goes in no later than seven days after receiving the protest committee’s written decision, with the reasons for it.', 'Как подать апелляцию в национальную федерацию: не позже семи дней после получения письменного решения протестового комитета, с указанием причин.']),
        app('S', ['Standard sailing instructions', 'Стандартная гоночная инструкция'], ['A ready-made set of sailing instructions an event may use in place of its own, if the notice of race says so.', 'Готовая гоночная инструкция, которую соревнование может использовать вместо своей, если это указано в положении.']),
        app('T', ['Arbitration', 'Арбитраж'], ['Applies only if the event says so. Before a hearing an arbitrator gives an opinion on what the protest committee would likely decide, and a boat may take a Post-Race Penalty, a 30% scoring penalty, instead of going on to a hearing.', 'Действует, только если это указано для соревнования. До рассмотрения арбитр высказывает мнение о вероятном решении протестового комитета, и лодка может принять послегоночное наказание — штраф 30% очков — вместо рассмотрения.']),
      ] }] },

    { id: 'signals', chip: t('Signals', 'Сигналы'), title: t('Race signals', 'Гоночные сигналы'),
      intro: t('What the race committee’s flags mean. Shown over a class flag, a signal applies to that class only.', 'Что значат флаги гоночного комитета. Сигнал над флагом класса относится только к этому классу.'),
      sections: [
        sec('signals-postponement', ['Postponement', 'Откладывание'], null, [
          sig('ap', 'AP', ['Answering pennant', 'Ответный вымпел'], ['Races not started are postponed. Two sounds. The warning signal comes 1 minute after it is lowered, unless the race is postponed again or abandoned.', 'Не начатые гонки отложены. Два звука. Предупреждение — через 1 минуту после спуска, если гонку снова не отложат и не прекратят.']),
          sig('ap-h', 'AP/H', ['AP over H', 'AP над H'], ['Races not started are postponed. Further signals ashore.', 'Не начатые гонки отложены. Дальнейшие сигналы — на берегу.']),
          sig('ap-a', 'AP/A', ['AP over A', 'AP над A'], ['Races not started are postponed. No more racing today.', 'Не начатые гонки отложены. Сегодня гонок больше не будет.']),
          sig('ap-num', 'AP/1–9', ['AP over a numeral pennant', 'AP над цифровым вымпелом'], ['Postponement of 1 to 9 hours from the scheduled starting time.', 'Откладывание на 1–9 часов от назначенного времени старта.']),
        ]),
        sec('signals-abandonment', ['Abandonment', 'Прекращение'], null, [
          sig('n', 'N', ['Flag N', 'Флаг N'], ['All races in progress are abandoned. Return to the starting area. Three sounds. The warning signal comes 1 minute after it is lowered, unless the race is abandoned again or postponed.', 'Все идущие гонки прекращены. Вернитесь в район старта. Три звука. Предупреждение — через 1 минуту после спуска, если гонку снова не прекратят и не отложат.']),
          sig('n-h', 'N/H', ['N over H', 'N над H'], ['All races in progress are abandoned. Further signals ashore.', 'Все идущие гонки прекращены. Дальнейшие сигналы — на берегу.']),
          sig('n-a', 'N/A', ['N over A', 'N над A'], ['All races in progress are abandoned. No more racing today.', 'Все идущие гонки прекращены. Сегодня гонок больше не будет.']),
        ]),
        sec('signals-start', ['Preparatory signals', 'Подготовительные сигналы'], null, [
          sig('p', 'P', ['Flag P', 'Флаг P'], ['The preparatory signal.', 'Подготовительный сигнал.']),
          sig('i', 'I', ['Flag I', 'Флаг I'], ['Rule 30.1 is in effect.', 'Действует правило 30.1.']),
          sig('z', 'Z', ['Flag Z', 'Флаг Z'], ['Rule 30.2 is in effect: a 20% scoring penalty.', 'Действует правило 30.2: штраф 20% очков.']),
          sig('u', 'U', ['Flag U', 'Флаг U'], ['Rule 30.3 is in effect: disqualification unless the race is restarted or resailed.', 'Действует правило 30.3: дисквалификация, если гонку не перестартуют и не проведут заново.']),
          sig('black', '', ['Black flag', 'Чёрный флаг'], ['Rule 30.4 is in effect: disqualification, even if the race is restarted or resailed.', 'Действует правило 30.4: дисквалификация, даже если гонку перестартуют или проведут заново.']),
        ]),
        sec('signals-recall', ['Recalls', 'Отзывы'], null, [
          sig('x', 'X', ['Flag X', 'Флаг X'], ['Individual recall, with one sound.', 'Индивидуальный отзыв, один звук.']),
          sig('first-sub', '1st', ['First Substitute', 'Первый заменяющий'], ['General recall, with two sounds. The warning signal comes 1 minute after it is lowered.', 'Общий отзыв, два звука. Предупреждение — через 1 минуту после спуска.']),
        ]),
        sec('signals-course', ['The course', 'Дистанция'], null, [
          sig('s', 'S', ['Flag S', 'Флаг S'], ['The course has been shortened, with two sounds. Rule 32.2 is in effect.', 'Дистанция сокращена, два звука. Действует правило 32.2.']),
          sig('c', 'C', ['Flag C', 'Флаг C'], ['The position of the next mark has been changed, with repetitive sounds: to starboard, to port, to shorten the leg or to lengthen it.', 'Положение следующего знака изменено, повторяющиеся звуки: вправо, влево, отрезок короче или длиннее.']),
          sig('m', 'M', ['Flag M', 'Флаг M'], ['The object showing this flag replaces a missing mark.', 'Предмет с этим флагом заменяет пропавший знак.']),
        ]),
        sec('signals-other', ['Other signals', 'Другие сигналы'], null, [
          sig('l', 'L', ['Flag L', 'Флаг L'], ['Ashore: a notice to competitors has been posted. Afloat: come within hail or follow this vessel.', 'На берегу: вывешено сообщение для гонщиков. На воде: подойдите на расстояние оклика или следуйте за этим судном.']),
          sig('y', 'Y', ['Flag Y', 'Флаг Y'], ['Wear a personal flotation device (rule 40), with one sound.', 'Наденьте спасательный жилет (правило 40), один звук.']),
          sig('v', 'V', ['Flag V', 'Флаг V'], ['Monitor the communication channel for safety instructions (rule 37), with one sound.', 'Слушайте канал связи для указаний по безопасности (правило 37), один звук.']),
          sig('orange', '', ['Orange flag', 'Оранжевый флаг'], ['The staff showing this flag is one end of the starting line. No sound.', 'Шест с этим флагом — один конец стартовой линии. Без звука.']),
          sig('blue', '', ['Blue flag', 'Синий флаг'], ['The staff showing this flag is one end of the finishing line. No sound.', 'Шест с этим флагом — один конец финишной линии. Без звука.']),
        ]),
      ] },
  ];
}
